    "cpp": "#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <string>\nusing namespace std;\nstruct St{ string name; int score; };\nint main(){\n    int n; cin>>n; vector<St> a(n);\n    for(int i=0;i<n;i++) cin>>a[i].name>>a[i].score;\n    sort(a.begin(),a.end(),[](const St& x,const St& y){\n        if(x.score!=y.score) return x.score>y.score;\n        return x.name<y.name;\n    });\n    for(int i=0;i<n;i++) cout<<a[i].name<<(i+1<n?\" \":\"\");\n    cout<<endl; return 0;\n}",
    "python": "n=int(input())\nst=[]\nfor _ in range(n):\n    name,score=input().split()\n    st.append((int(score),name))\nst.sort(key=lambda x:(-x[0],x[1]))\nprint(\" \".join(name for _,name in st))",
    "java": "import java.util.*;\nclass Main{\n  public static void main(String[] __wb){\n    Scanner sc=new Scanner(System.in);\n    int n=sc.nextInt(); String[] names=new String[n];\n    int[] scores=new int[n];\n    for(int i=0;i<n;i++){ names[i]=sc.next(); scores[i]=sc.nextInt(); }\n    Integer[] idx=new Integer[n];\n    for(int i=0;i<n;i++) idx[i]=i;\n    Arrays.sort(idx, (p,q)->{ if(scores[p]!=scores[q]) return scores[q]-scores[p]; return names[p].compareTo(names[q]); });\n    for(int i=0;i<n;i++){ if(i>0) System.out.print(\" \"); System.out.print(names[idx[i]]); }\n    System.out.println();\n  }\n}\n"
