    "cpp": "#include <iostream>\n#include <vector>\nusing namespace std;\nint main(){\n    int m,n; cin>>m>>n; vector<vector<int>> a(m,vector<int>(n));\n    for(int i=0;i<m;i++) for(int j=0;j<n;j++) cin>>a[i][j];\n    for(int i=0;i<m;i++){ int s=0; for(int j=0;j<n;j++) s+=a[i][j]; cout<<s<<endl; }\n    for(int j=0;j<n;j++){ int s=0; for(int i=0;i<m;i++) s+=a[i][j]; cout<<s<<endl; }\n    return 0;\n}",
