    "cpp": "#include <iostream>\n#include <string>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nstring mul(string a, string b){\n    reverse(a.begin(),a.end()); reverse(b.begin(),b.end());\n    int c[2000]={0};\n    for(int i=0;i<a.size();i++) for(int j=0;j<b.size();j++) c[i+j]+=(a[i]-48)*(b[j]-48);\n    string s; int carry=0;\n    for(int i=0;i<2000;i++){ int v=c[i]+carry; s+=char(v%10+48); carry=v/10; }\n    while(s.size()>1 && s.back()==48) s.pop_back();\n    reverse(s.begin(),s.end()); return s;\n}\nint main(){\n    string a; int b; cin>>a>>b;\n    string r=\"1\";\n    for(int i=0;i<b;i++) r=mul(r,a);\n    cout<<r<<endl; return 0;\n}",
    "python": "a,b=input().split(); b=int(b)\nr=\"1\"\nfor _ in range(b):\n    x=r[::-1]; y=a[::-1]; c=[0]*(len(x)+len(y))\n    for i in range(len(x)):\n        for j in range(len(y)):\n            c[i+j]+=int(x[i])*int(y[j])\n    s=[]; carry=0\n    for v in c:\n        v+=carry; s.append(str(v%10)); carry=v//10\n    while carry: s.append(str(carry%10)); carry//=10\n    while len(s)>1 and s[-1]==\"0\": s.pop()\n    r=\"\".join(reversed(s))\nprint(r)",
    "java": "class Main{\n    public static void main(String[] __wb){\n        java.util.Scanner sc=new java.util.Scanner(System.in);\n        java.math.BigInteger x=new java.math.BigInteger(sc.next());\n        int y=sc.nextInt();\n        System.out.println(x.pow(y));\n    }\n}"
