    "cpp": "#include <iostream>\n#include <cmath>\n#include <cstdio>\nusing namespace std;\nint main(){double a,b,c;cin>>a>>b>>c;if(a==0){cout<<\"No\"<<endl;return 0;}double d=b*b-4*a*c;if(d<0){cout<<\"No\"<<endl;return 0;}double r1=(-b-sqrt(d))/(2*a),r2=(-b+sqrt(d))/(2*a);if(r1>r2){double t=r1;r1=r2;r2=t;}printf(\"%.2f %.2f\\n\",r1,r2);return 0;}",
    "python": "import sys,math\na,b,c=map(float,sys.stdin.read().split())\nif a==0:\n    print(\"No\")\nelse:\n    d=b*b-4*a*c\n    if d<0:\n        print(\"No\")\n    else:\n        r1=(-b-math.sqrt(d))/(2*a)\n        r2=(-b+math.sqrt(d))/(2*a)\n        if r1>r2: r1,r2=r2,r1\n        print(\"%.2f %.2f\"%(r1,r2))",
    "java": "import java.util.Scanner;\nclass Main{public static void main(String[] __wb){Scanner s=new Scanner(System.in);double A=s.nextDouble(),B=s.nextDouble(),C=s.nextDouble();if(A==0){System.out.println(\"No\");return;}double d=B*B-4*A*C;if(d<0){System.out.println(\"No\");return;}double r1=(-B-Math.sqrt(d))/(2*A),r2=(-B+Math.sqrt(d))/(2*A);if(r1>r2){double t=r1;r1=r2;r2=t;}System.out.printf(\"%.2f %.2f\\n\",r1,r2);}}"
