    "cpp": "#include <iostream>\n#include <vector>\nusing namespace std;\nint main(){\n    int n; cin>>n; vector<int> a(n),o,e;\n    for(int i=0;i<n;i++){ cin>>a[i]; if(a[i]%2!=0) o.push_back(a[i]); else e.push_back(a[i]); }\n    bool f=true;\n    for(int v:o){ if(!f) cout<<' '; cout<<v; f=false; }\n    for(int v:e){ if(!f) cout<<' '; cout<<v; f=false; }\n    cout<<endl;\n    return 0;\n}",
