    "cpp": "#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nstruct St{ string name; int m,e; };\nint main(){\n    int n; cin>>n; vector<St> v(n);\n    for(int i=0;i<n;i++) cin>>v[i].name>>v[i].m>>v[i].e;\n    sort(v.begin(),v.end(),[](St x,St y){\n        if(x.m!=y.m) return x.m>y.m;\n        if(x.e!=y.e) return x.e>y.e;\n        return x.name<y.name;\n    });\n    for(auto& s:v) cout<<s.name<<' '<<s.m<<' '<<s.e<<endl;\n    return 0;\n}",
    "python": "import sys\nlines=sys.stdin.read().splitlines()\nn=int(lines[0])\nst=[]\nfor i in range(1,n+1):\n    p=lines[i].split()\n    st.append((p[0],int(p[1]),int(p[2])))\nst.sort(key=lambda x:(-x[1],-x[2],x[0]))\nfor name,m,e in st: print(name,m,e)",
    "java": "import java.util.Scanner;\nimport java.util.Arrays;\nclass Main{\n    static class St{ String name; int m,e; }\n    public static void main(String[] __wb){\n        Scanner sc=new Scanner(System.in);\n        int n=sc.nextInt(); St[] v=new St[n];\n        for(int i=0;i<n;i++){ v[i]=new St(); v[i].name=sc.next(); v[i].m=sc.nextInt(); v[i].e=sc.nextInt(); }\n        Arrays.sort(v,(x,y)-> x.m!=y.m? y.m-x.m : (x.e!=y.e? y.e-x.e : x.name.compareTo(y.name)));\n        for(St s: v) System.out.println(s.name+\" \"+s.m+\" \"+s.e);\n    }\n}"
