    "cpp": "#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nstruct T{ int a,b,c; };\nint main(){\n    int n; cin>>n; vector<T> v(n);\n    for(int i=0;i<n;i++) cin>>v[i].a>>v[i].b>>v[i].c;\n    sort(v.begin(),v.end(),[](T x,T y){\n        if(x.a!=y.a) return x.a<y.a;\n        if(x.b!=y.b) return x.b<y.b;\n        return x.c<y.c;\n    });\n    for(auto& t:v) cout<<t.a<<' '<<t.b<<' '<<t.c<<endl;\n    return 0;\n}",
    "python": "import sys\nlines=sys.stdin.read().splitlines()\nn=int(lines[0])\narr=[]\nfor i in range(1,n+1):\n    p=list(map(int,lines[i].split()))\n    arr.append(p)\narr.sort()\nfor row in arr: print(' '.join(map(str,row)))",
    "java": "import java.util.Scanner;\nimport java.util.Arrays;\nclass Main{\n    static class T{ int a,b,c; }\n    public static void main(String[] __wb){\n        Scanner sc=new Scanner(System.in);\n        int n=sc.nextInt(); T[] v=new T[n];\n        for(int i=0;i<n;i++){ v[i]=new T(); v[i].a=sc.nextInt(); v[i].b=sc.nextInt(); v[i].c=sc.nextInt(); }\n        Arrays.sort(v,(x,y)-> x.a!=y.a? x.a-y.a : (x.b!=y.b? x.b-y.b : x.c-y.c));\n        for(T t: v) System.out.println(t.a+\" \"+t.b+\" \"+t.c);\n    }\n}"
