    "cpp": "#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\nint main(){\n    int n; cin>>n;\n    priority_queue<int,vector<int>,greater<int>> pq;\n    for(int i=0;i<n;i++){ int x; cin>>x; pq.push(x); }\n    long long ans=0;\n    while(pq.size()>1){ int a=pq.top(); pq.pop(); int b=pq.top(); pq.pop(); int s=a+b; ans+=s; pq.push(s); }\n    cout<<ans<<endl;\n    return 0;\n}\n",
    "python": "import heapq, sys\ndata=list(map(int,sys.stdin.read().split()))\nn=data[0]; h=data[1:]\nheapq.heapify(h); ans=0\nwhile len(h)>1:\n    a=heapq.heappop(h); b=heapq.heappop(h); s=a+b; ans+=s; heapq.heappush(h,s)\nprint(ans)\n",
