    "cpp": "#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nint n, k;\nvector<int> a, comb;\nvoid dfs(int i, int cnt) {\n    if (cnt == k) {\n        for (int j = 0; j < k; j++) cout << comb[j] << (j == k-1 ? \"\" : \" \");\n        cout << endl;\n        return;\n    }\n    if (i >= n) return;\n    comb.push_back(a[i]); dfs(i+1, cnt+1); comb.pop_back();\n    dfs(i+1, cnt);\n}\nint main() {\n    cin >> n >> k;\n    a.resize(n);\n    for (int i = 0; i < n; i++) cin >> a[i];\n    sort(a.begin(), a.end());\n    dfs(0, 0);\n    return 0;\n}",
    "python": "import sys\nimport itertools\ndef main():\n    d = sys.stdin.read().split()\n    n = int(d[0]); k = int(d[1])\n    a = sorted(map(int, d[2:2+n]))\n    for comb in itertools.combinations(a, k):\n        print(' '.join(map(str, comb)))\nmain()",
