    "cpp": "#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v; cin >> u >> v;\n        adj[u].push_back(v); adj[v].push_back(u);\n    }\n    vector<bool> vis(n + 1, false);\n    queue<int> q; q.push(1); vis[1] = true; int cnt = 1;\n    while (!q.empty()) {\n        int u = q.front(); q.pop();\n        for (int v : adj[u]) if (!vis[v]) { vis[v] = true; cnt++; q.push(v); }\n    }\n    cout << (cnt == n ? \"YES\" : \"NO\") << endl;\n    return 0;\n}",
    "python": "import sys\nfrom collections import deque\ndef main():\n    d = sys.stdin.read().split()\n    n = int(d[0]); m = int(d[1])\n    adj = [[] for _ in range(n + 1)]\n    idx = 2\n    for _ in range(m):\n        u = int(d[idx]); v = int(d[idx+1]); idx += 2\n        adj[u].append(v); adj[v].append(u)\n    vis = [False] * (n + 1)\n    q = deque([1]); vis[1] = True; cnt = 1\n    while q:\n        u = q.popleft()\n        for v in adj[u]:\n            if not vis[v]:\n                vis[v] = True; cnt += 1; q.append(v)\n    print(\"YES\" if cnt == n else \"NO\")\nmain()",
    "java": "import java.util.*;\nclass Main {\n    public static void main(String[] __wb) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt(), m = sc.nextInt();\n        List<List<Integer>> adj = new ArrayList<>();\n        for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());\n        for (int i = 0; i < m; i++) { int u = sc.nextInt(), v = sc.nextInt(); adj.get(u).add(v); adj.get(v).add(u); }\n        boolean[] vis = new boolean[n + 1];\n        Queue<Integer> q = new LinkedList<>(); q.add(1); vis[1] = true; int cnt = 1;\n        while (!q.isEmpty()) {\n            int u = q.poll();\n            for (int v : adj.get(u)) if (!vis[v]) { vis[v] = true; cnt++; q.add(v); }\n        }\n        System.out.println(cnt == n ? \"YES\" : \"NO\");\n    }\n}"
