  "desc": "输入一棵 n 个节点的树（以节点 1 为根），输出这棵树的最大深度，即以 1 为根时离根最远的节点到根经过的边数。",
  "input": "第一行一个整数 n；接下来 n-1 行每行两个整数 u, v 表示一条边。",
  "output": "一行，一个整数，表示树的最大深度（边数）。",
  "samples": [
    {
      "input": "5\n1 2\n1 3\n2 4\n2 5",
      "output": "2"
    }
  ],
  "solutions": {
    "cpp": "#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\nint main() {\n    int n;\n    cin >> n;\n    vector<vector<int>> adj(n + 1);\n    for (int k = 0; k < n - 1; k++) {\n        int u, v; cin >> u >> v;\n        adj[u].push_back(v); adj[v].push_back(u);\n    }\n    vector<int> d(n + 1, -1);\n    queue<int> q;\n    d[1] = 0; q.push(1);\n    while (!q.empty()) {\n        int u = q.front(); q.pop();\n        for (int v : adj[u])\n            if (d[v] == -1) { d[v] = d[u] + 1; q.push(v); }\n    }\n    int ans = 0;\n    for (int i = 1; i <= n; i++) if (d[i] > ans) ans = d[i];\n    cout << ans << endl;\n    return 0;\n}",
    "python": "import sys\nfrom collections import deque\ndata = sys.stdin.read().split()\nn = int(data[0])\nadj = [[] for _ in range(n + 1)]\ni = 1\nfor _ in range(n - 1):\n    u = int(data[i]); v = int(data[i + 1]); i += 2\n    adj[u].append(v); adj[v].append(u)\nd = [-1] * (n + 1); d[1] = 0\nq = deque([1])\nwhile q:\n    u = q.popleft()\n    for v in adj[u]:\n        if d[v] == -1:\n            d[v] = d[u] + 1; q.append(v)\nprint(max(d))",
    "java": "import java.util.*;\nclass Main {\n    public static void main(String[] __wb) {\n        Scanner in = new Scanner(System.in);\n        int n = in.nextInt();\n        ArrayList<Integer>[] adj = new ArrayList[n + 1];\n        for (int i = 1; i <= n; i++) adj[i] = new ArrayList<>();\n        for (int k = 0; k < n - 1; k++) {\n            int u = in.nextInt(), v = in.nextInt();\n            adj[u].add(v); adj[v].add(u);\n        }\n        int[] d = new int[n + 1];\n        Arrays.fill(d, -1);\n        Queue<Integer> q = new LinkedList<>();\n        d[1] = 0; q.add(1);\n        while (!q.isEmpty()) {\n            int u = q.poll();\n            for (int v : adj[u])\n                if (d[v] == -1) { d[v] = d[u] + 1; q.add(v); }\n        }\n        int ans = 0;\n        for (int i = 1; i <= n; i++) if (d[i] > ans) ans = d[i];\n        System.out.println(ans);\n    }\n}"
  },
  "algo": [
    "广度优先搜索",
    "树形结构"
  ]
