    "cpp": "#include <iostream>\n#include <cmath>\n#include <iomanip>\nusing namespace std;\nint main() {\n    double a, b, c;\n    cin >> a >> b >> c;\n    if (a + b > c && a + c > b && b + c > a) {\n        double p = (a + b + c) / 2;\n        double s = sqrt(p * (p - a) * (p - b) * (p - c));\n        cout.precision(2);\n        cout << fixed << s << endl;\n    } else {\n        cout << \"error\" << endl;\n    }\n    return 0;\n}",
    "python": "import math\na, b, c = map(float, input().split())\nif a + b > c and a + c > b and b + c > a:\n    p = (a + b + c) / 2\n    print(f\"{math.sqrt(p * (p - a) * (p - b) * (p - c)):.2f}\")\nelse:\n    print(\"error\")",
