    "cpp": "int n,m;cin>>n>>m;\nvector<vector<int>>E(n+1);\nfor(int i=0;i<m;i++){int u,v;cin>>u>>v;E[u].push_back(v);E[v].push_back(u);}\nint st;cin>>st;\nvector<int>dist(n+1,-1); queue<int>q; dist[st]=0; q.push(st);\nwhile(!q.empty()){int x=q.front();q.pop(); for(int y:E[x]) if(dist[y]<0){dist[y]=dist[x]+1;q.push(y);}}\nfor(int i=1;i<=n;i++){ if(i>1)cout<<' '; cout<<dist[i]; }\ncout<<'\\n';",
    "python": "import sys\nfrom collections import deque\nd=list(map(int,sys.stdin.read().split()))\nit=iter(d)\nn=next(it);m=next(it);\nE=[[] for _ in range(n+1)]\nfor _ in range(m):\n u=next(it);v=next(it); E[u].append(v); E[v].append(u)\ns=next(it)\ndist=[-1]*(n+1); dist[s]=0; q=deque([s])\nwhile q:\n x=q.popleft()\n for y in E[x]:\n  if dist[y]<0: dist[y]=dist[x]+1; q.append(y)\nprint(' '.join(str(dist[i]) for i in range(1,n+1)))",
