    "cpp": "#include <bits/stdc++.h>\nusing namespace std;\nint main(){ios::sync_with_stdio(false);cin.tie(nullptr);\nint y,m,d;cin>>y>>m>>d;\nint tab[13]={0,3,3,6,1,4,6,2,5,0,2,5,3};\nint yy=y; if(m<3) yy--;\nint leap=(yy/4-yy/100+yy/400);\nint w=(yy+yy/4-yy/100+yy/400+tab[m]+d)%7;\nstatic const char*n[]={\"Sun\",\"Mon\",\"Tue\",\"Wed\",\"Thu\",\"Fri\",\"Sat\"};\ncout<<n[w]<<'\\n';\n  return 0;}\n",
    "python": "import datetime\ny,m,d=map(int,input().split())\nw=datetime.date(y,m,d).weekday()\nnames=['Mon','Tue','Wed','Thu','Fri','Sat','Sun']\nprint(names[w])",
    "java": "import java.util.*;\nclass Main{\n  public static void main(String[] args){\n    Scanner sc = new java.util.Scanner(System.in);\nint y=sc.nextInt(),m=sc.nextInt(),d=sc.nextInt();\nint tab[]={0,3,3,6,1,4,6,2,5,0,2,5,3};\nint yy=y; if(m<3) yy--;\nint w=(yy+yy/4-yy/100+yy/400+tab[m]+d)%7;\nString n[]={\"Sun\",\"Mon\",\"Tue\",\"Wed\",\"Thu\",\"Fri\",\"Sat\"};\nSystem.out.println(n[w]);\n}\n"
