    "cpp": "#include<iostream>\nusing namespace std;\nint main(){long long m,n;cin>>m>>n;long long ans=1;long long k=m-1;if(n-1<k)k=n-1;for(long long i=1;i<=k;i++)ans=ans*(m+n-2-i+1)/i;cout<<ans<<endl;return 0;}\n",
    "python": "import sys,math\nv=[int(x) for x in sys.stdin.read().split()]\nm,n=v[0],v[1]\nans=math.comb(m+n-2, m-1)\nprint(ans)\n",
