    "cpp": "#include<iostream>\n#include<vector>\nusing namespace std;\nint main(){long long n;cin>>n;vector<long long>a(n);for(int i=0;i<n;i++)cin>>a[i];\nset<long long>s;for(int i=0;i<n;i++)if(a[i]>0)s.insert(a[i]);long long ans=s.size();\ncout<<ans<<endl;return 0;}\n",
    "python": "import sys\nv=[int(x) for x in sys.stdin.read().split()]\nn=v[0]; a=v[1:]\nans=len(set(x for x in a if x>0))\nprint(ans)\n",
