    "cpp": "int n,m;cin>>n>>m;vector<vector<pair<int,int>>>g(n+1);for(int i=0;i<m;i++){int u,v,w;cin>>u>>v>>w;g[u].push_back({v,w});g[v].push_back({u,w});}int s,t;cin>>s>>t;const long long INF=1e18;vector<long long>d(n+1,INF);d[s]=0;priority_queue<pair<long long,int>,vector<pair<long long,int>>,greater<>>pq;pq.push({0,s});while(!pq.empty()){auto[du,u]=pq.top();pq.pop();if(du>d[u])continue;for(auto[v,w]:g[u])if(d[v]>d[u]+w){d[v]=d[u]+w;pq.push({d[v],v});}}cout<<(d[t]<INF?d[t]:-1)<<'\\n';",
    "python": "import heapq\nn,m=map(int,input().split())\ng=[[] for _ in range(n+1)]\nfor _ in range(m):\n    u,v,w=map(int,input().split());g[u].append((v,w));g[v].append((u,w))\ns,t=map(int,input().split())\nimport sys\nINF=10**18\nd=[INF]*(n+1);d[s]=0;pq=[(0,s)]\nwhile pq:\n    du,u=heapq.heappop(pq)\n    if du>d[u]:continue\n    for v,w in g[u]:\n        if d[v]>d[u]+w:d[v]=d[u]+w;heapq.heappush(pq,(d[v],v))\nprint(d[t] if d[t]<INF else -1)",
    "java": "int n=sc.nextInt(),m=sc.nextInt();java.util.ArrayList<int[]>[]g=new java.util.ArrayList[n+1];for(int i=1;i<=n;i++)g[i]=new java.util.ArrayList<>();for(int i=0;i<m;i++){int u=sc.nextInt(),v=sc.nextInt(),w=sc.nextInt();g[u].add(new int[]{v,w});g[v].add(new int[]{u,w});}int s=sc.nextInt(),t=sc.nextInt();long INF=1000000000000000000L;long[]d=new long[n+1];java.util.Arrays.fill(d,INF);d[s]=0;java.util.PriorityQueue<long[]>pq=new java.util.PriorityQueue<>((a,b)->Long.compare(a[0],b[0]));pq.add(new long[]{0,s});while(!pq.isEmpty()){long[]cur=pq.poll();long du=cur[0];int u=(int)cur[1];if(du>d[u])continue;for(int[]e:g[u]){int v=e[0],w=e[1];if(d[v]>d[u]+w){d[v]=d[u]+w;pq.add(new long[]{d[v],v});}}}System.out.println(d[t]<INF?d[t]:-1);"
