  "solutions": {
    "cpp": "#include<iostream>\n#include<vector>\nusing namespace std;\nint main(){long long n;cin>>n;vector<long long>a(n);for(int i=0;i<n;i++)cin>>a[i];\nvector<long long>ans;set<long long>seen;for(int i=0;i<n;i++)if(seen.find(a[i])==seen.end()){seen.insert(a[i]);ans.push_back(a[i]);}for(int i=0;i<ans.size();i++)cout<<ans[i]<<(i+1==ans.size()?\"\":\" \");\nreturn 0;}\n",
    "python": "import sys\nv=[int(x) for x in sys.stdin.read().split()]\nn=v[0]; a=v[1:]\nseen=set();ans=[]\nfor x in a:\n if x not in seen: seen.add(x); ans.append(x)\nprint(' '.join(map(str,ans)))\n",
    "java": "import java.util.*;\npublic class Main{public static void main(String[]x){Scanner sc=new Scanner(System.in);long n=sc.nextLong();long[]a=new long[(int)n];for(int i=0;i<n;i++)a[i]=sc.nextLong();\njava.util.LinkedHashSet<Long>seen=new java.util.LinkedHashSet<>();for(int i=0;i<n;i++)seen.add(a[i]);long[]ans=seen.stream().mapToLong(x->x).toArray();for(int i=0;i<ans.length;i++)System.out.print(ans[i]+(i+1==ans.length?\"\":\" \"));}}\n"
  }
