    "cpp": "int n,m;cin>>n>>m;\nvector<vector<int>>g(n+1); vector<int>ind(n+1,0);\nfor(int i=0;i<m;i++){int u,v;cin>>u>>v; g[u].push_back(v); ind[v]++;}\nqueue<int>q; for(int i=1;i<=n;i++) if(ind[i]==0) q.push(i);\nvector<int>o; while(!q.empty()){int x=q.front();q.pop(); o.push_back(x); for(int y:g[x]) if(--ind[y]==0) q.push(y);}\nif((int)o.size()!=n){cout<<-1<<'\\n';}\nelse{ for(int i=0;i<n;i++){ if(i)cout<<' '; cout<<o[i]; } cout<<'\\n'; }",
    "python": "import sys\nfrom collections import deque\nd=list(map(int,sys.stdin.read().split()))\nit=iter(d); n=next(it);m=next(it);\ng=[[] for _ in range(n+1)]; inde=[0]*(n+1)\nfor _ in range(m): u=next(it);v=next(it); g[u].append(v); inde[v]+=1\nq=deque([i for i in range(1,n+1) if inde[i]==0]); out=[]\nwhile q:\n x=q.popleft(); out.append(x)\n for y in g[x]:\n  inde[y]-=1\n  if inde[y]==0: q.append(y)\nprint(' '.join(map(str,out)) if len(out)==n else -1)",
