    "cpp": "int n,m;cin>>n>>m;\nvector<vector<int>>E(n+1);\nfor(int i=0;i<m;i++){int u,v;cin>>u>>v;E[u].push_back(v);E[v].push_back(u);}\nint st;cin>>st;\nvector<int>dist(n+1,-1); queue<int>q; dist[st]=0; q.push(st);\nwhile(!q.empty()){int x=q.front();q.pop(); for(int y:E[x]) if(dist[y]<0){dist[y]=dist[x]+1;q.push(y);}}\nfor(int i=1;i<=n;i++){ if(i>1)cout<<' '; cout<<dist[i]; }\ncout<<'\\n';",
