  "solutions": {
    "cpp": "string s;int fr,to;cin>>s>>fr>>to;long long v=0;for(char c:s){int d=c>='0'&&c<='9'?c-'0':(c>='a'&&c<='f'?c-'a'+10:0);v=v*fr+d;}if(to==10){cout<<v<<'\\n';}else{string out;if(v==0)out='0';while(v){int d=v%to;out=(d<10?char('0'+d):char('a'+d-10))+out;v/=to;}cout<<out<<'\\n';}",
    "python": "s,b,t=input().split()\nb=int(b);t=int(t)\nprint(format(int(s,b),'d') if t==10 else format(int(s,b),{2:'b',8:'o',16:'x'}[t]))",
    "java": "String s=sc.next();int fr=sc.nextInt(),to=sc.nextInt();long v=0;for(char c:s.toCharArray()){int d=Character.isDigit(c)?c-'0':(c-'a'+10);v=v*fr+d;}if(to==10)System.out.println(v);else{StringBuilder out=new StringBuilder();if(v==0)out.append('0');while(v>0){int d=(int)(v%to);out.insert(0,d<10?(char)('0'+d):(char)('a'+d-10));v/=to;}System.out.println(out);}"
  }
