  "solutions": {
    "cpp": "int k;cin>>k;if(k==1){cout<<2<<'\\n';return 0;}int limit=700000;vector<bool>sieve(limit+1,true);sieve[0]=sieve[1]=false;int c=0;for(int i=2;i<=limit;i++){if(sieve[i]){c++;if(c==k){cout<<i<<'\\n';break;}for(int j=i*i;j<=limit;j+=i)sieve[j]=false;}}",
    "python": "import math\nk=int(input())\nif k==1:print(2)\nelse:\n    limit=int(k*(math.log(k)+math.log(math.log(k))))+10\n    if limit<100:limit=100\n    sieve=[True]*(limit+1);sieve[0]=sieve[1]=False\n    c=0\n    for i in range(2,limit+1):\n        if sieve[i]:\n            c+=1\n            if c==k:print(i);break\n            for j in range(i*i,limit+1,i):sieve[j]=False\n",
    "java": "int k=sc.nextInt();if(k==1){System.out.println(2);return;}int limit=700000;boolean[]sieve=new boolean[limit+1];for(int i=2;i<=limit;i++)sieve[i]=true;int c=0;for(int i=2;i<=limit;i++){if(sieve[i]){c++;if(c==k){System.out.println(i);break;}for(int j=i*i;j<=limit;j+=i)sieve[j]=false;}}"
  }
