    "cpp": "#include <bits/stdc++.h>\nusing namespace std;\nint main(){ios::sync_with_stdio(false);cin.tie(nullptr);\nint t;cin>>t;\nfor(int i=0;i<t;i++){ long long x;cin>>x; if(x<2){cout<<'N';continue;}\n  bool ok=true; for(long long d=2;d*d<=x;d++) if(x%d==0){ok=false;break;}\n  cout<<(ok?'Y':'N'); }\ncout<<'\\n';\n  return 0;}\n",
    "python": "import sys\nv=[int(x) for x in sys.stdin.read().split()]\ndef isp(x):\n    if x<2: return False\n    i=2\n    while i*i<=x:\n        if x%i==0: return False\n        i+=1\n    return True\nprint(' '.join('Y' if isp(x) else 'N' for x in v[1:]))",
