  "solutions": {
    "cpp": "#include<iostream>\n#include<vector>\nusing namespace std;\nint main(){long long n;cin>>n;vector<long long>a(n);for(int i=0;i<n;i++)cin>>a[i];long long best=a[0],cur=a[0];for(int i=1;i<n;i++){cur=(a[i]>cur+a[i]?a[i]:cur+a[i]);if(cur>best)best=cur;}cout<<best<<endl;return 0;}\n",
    "python": "import sys\nv=[int(x) for x in sys.stdin.read().split()]\nn=v[0];a=v[1:1+n]\nbest=cur=a[0]\nfor x in a[1:]:\n cur=max(x,cur+x); best=max(best,cur)\nans=best\nprint(ans)\n",
    "java": "import java.util.*;\npublic class Main{public static void main(String[]x){Scanner sc=new Scanner(System.in);long n=sc.nextLong();long[]a=new long[(int)n];for(int i=0;i<n;i++)a[i]=sc.nextLong();long best=a[0],cur=a[0];for(int i=1;i<n;i++){cur=(a[i]>cur+a[i]?a[i]:cur+a[i]);if(cur>best)best=cur;}System.out.println(best);}}\n"
  }
