  "solutions": {
    "cpp": "#include<iostream>\nusing namespace std;\nint main(){long long n;cin>>n;\nlong long ans=1;t=n;set<long long>seen;while(t!=1&&seen.find(t)==seen.end()){seen.insert(t);long long s=0;long long x=t;while(x){s+=(x%10)*(x%10);x/=10;}t=s;}if(t!=1)ans=0;\ncout<<ans<<endl;return 0;}\n",
    "python": "import sys\nn=int(sys.stdin.readline().strip())\nseen=set()\nwhile n!=1 and n not in seen:\n seen.add(n); n=sum(int(c)**2 for c in str(n))\nans=1 if n==1 else 0\nprint(ans)\n",
    "java": "import java.util.*;\npublic class Main{public static void main(String[]x){Scanner sc=new Scanner(System.in);long n=sc.nextLong();\nlong ans=1;t=n;java.util.HashSet<Long>seen=new java.util.HashSet<>();while(t!=1&&!seen.contains(t)){seen.add(t);long s=0;long x=t;while(x>0){s+=(x%10)*(x%10);x/=10;}t=s;}if(t!=1)ans=0;\nSystem.out.println(ans);}}\n"
  }
